const MRout=x=>1-(1-MRclamp(x))**3;
const MRrand=(i,s=0)=>{const n=Math.sin(i*137.37+s*71.913+1.78)*43758.5453;return n-Math.floor(n)};
const MRmix=(a,b,t)=>'#'+[1,3,5].map(k=>Math.round(parseInt(a.slice(k,k+2),16)*(1-t)+parseInt(b.slice(k,k+2),16)*t).toString(16).padStart(2,'0')).join('');
const MRrgba=(hex,a=1)=>{const n=parseInt(hex.slice(1),16);return `rgba(${n>>16},${n>>8&255},${n&255},${MRclamp(a)})`};
function MRpath(c,points,close=false){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));if(close)c.closePath()}
function MRline(c,points,col,width=.004,a=1){MRpath(c,points);c.strokeStyle=MRrgba(col,a);c.lineWidth=width;c.stroke()}
function MRellipse(c,x,y,rx,ry,col,a=1,stroke=false,width=.004){c.beginPath();c.ellipse(x,y,Math.max(.0001,rx),Math.max(.0001,ry),0,0,MR_TAU);if(stroke){c.strokeStyle=MRrgba(col,a);c.lineWidth=width;c.stroke()}else{c.fillStyle=MRrgba(col,a);c.fill()}}
function MRcurve(a,b,c,d,n=40){const pts=[];for(let i=0;i<=n;i++){const t=i/n,u=1-t;pts.push([u*u*u*a[0]+3*u*u*t*b[0]+3*u*t*t*c[0]+t*t*t*d[0],u*u*u*a[1]+3*u*u*t*b[1]+3*u*t*t*c[1]+t*t*t*d[1]])}return pts}
function MRglow(c,x,y,r,col,a){if(!(r>0)||!(a>0))return;const g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,MRrgba(col,a));g.addColorStop(.3,MRrgba(col,a*.3));g.addColorStop(1,MRrgba(col,0));c.fillStyle=g;c.beginPath();c.arc(x,y,r,0,MR_TAU);c.fill()}
