function MRdrop(c,x,y,r,col,q,stretch=1){c.save();c.translate(x,y);c.scale(1,stretch);const shape=()=>{c.beginPath();c.moveTo(0,-r*1.6);c.bezierCurveTo(r*.2,-r*.6,r,r*.02,r*.7,r*.65);c.bezierCurveTo(r*.4,r*1.22,-r*.75,r*1.15,-r*.8,r*.35);c.bezierCurveTo(-r*.84,-r*.24,-r*.2,-r*.8,0,-r*1.6);c.closePath()};MRmaterial(c,shape,col,q,.86,[-r,-r*1.6,r,r]);MRline(c,MRcurve([-r*.2,-r*.72],[-r*.55,-r*.2],[-r*.53,r*.3],[-r*.27,r*.5],16),'#ffffff',r*.1,.72);c.restore()}
