function MRumbrellas(c,q){q.nodes.forEach((n,i)=>{const col=q.p[i%q.p.length],r=n.r,pulse=MRpulse(q,i);c.save();c.translate(n.x,n.y+r*.72);c.rotate(q.reduced?0:Math.sin(q.clock*.65+i)*.055);MRline(c,MRcurve([0,0],[0,r*1.7],[r*.5,r*1.8],[r*.42,r*1.36]),q.p[3],.014,.8);for(let k=0;k<6;k++){const x0=-r+k/6*r*2,x1=-r+(k+1)/6*r*2;const shape=()=>{c.beginPath();c.moveTo(0,-r*.72);c.quadraticCurveTo(x0*.75,-r*.65,x0,0);c.quadraticCurveTo((x0+x1)/2,-r*.12,x1,0);c.quadraticCurveTo(x1*.75,-r*.65,0,-r*.72);c.closePath()};MRmaterial(c,shape,q.p[(i+(k%2))%q.p.length],q,.78,[-r,-r,r,0])}MRpearl(c,0,-r*.73,.014,q.p[3]);if(pulse)MRglow(c,0,-r*.2,r,col,.25*pulse);c.restore()})}
