function MRbamboo(c,q){q.nodes.forEach((n,i)=>{const col=q.p[i%q.p.length],r=n.r,bottom=.75,pulse=MRpulse(q,i);const shape=()=>{c.beginPath();c.roundRect(n.x-r*.45,n.y,r*.9,bottom-n.y,r*.25)};MRmaterial(c,shape,col,q,.8,[n.x-r,n.y,n.x+r,bottom]);for(let y=n.y+.16;y<bottom;y+=.18){MRellipse(c,n.x,y,r*.48,r*.12,col,.65,true,.006);MRellipse(c,n.x,y-.012,r*.46,r*.1,q.p[4],.4,true,.002)}MRellipse(c,n.x,n.y,r*.46,r*.19,MRmix(col,'#101633',.75),.9);MRellipse(c,n.x,n.y,r*.49,r*.21,q.p[4],.8,true,.006);MRglow(c,n.x,n.y,r*2,col,pulse*.38)});MRline(c,[[-1,.7],[1,.7]],q.p[2],.02,.5)}
function MRspiral(c,q){const pts=[];for(let i=0;i<=180;i++){const u=i/180,a=-Math.PI/2+u*Math.PI*4,r=.16+u*.74;pts.push([Math.cos(a)*r,Math.sin(a)*r*.68+.08])}MRline(c,pts,q.p[1],.032,.2);MRline(c,pts,q.p[3],.004,.7);q.nodes.forEach((n,i)=>{const col=q.p[i%q.p.length],pulse=MRpulse(q,i);MRglow(c,n.x,n.y,n.r*2,col,.15+pulse*.2);MRpearl(c,n.x,n.y,n.r*(1+pulse*.12),col,.9);MRellipse(c,n.x,n.y,n.r*1.18,n.r*.5,col,.5,true,.003)});}
