function MRsilk(c,q){q.nodes.forEach((n,i)=>{const col=q.p[i%q.p.length],pulse=MRpulse(q,i),left=[],right=[];for(let k=0;k<=60;k++){const u=k/60,y=-.77+u*1.43,x=n.x+Math.sin(u*5+q.clock*.75+i)*.065*Math.sin(u*Math.PI);left.push([x-.023-u*.012,y]);right.push([x+.023+u*.012,y])}MRmaterial(c,()=>MRpath(c,[...left,...right.reverse()],true),col,q,.53,[n.x-.1,-.8,n.x+.1,.7]);MRline(c,left,MRmix(col,'#ffffff',.55),.003,.7);MRpearl(c,n.x,-.78,.027,col);MRbowl(c,n.x,n.y,.095,col,q,pulse)});MRline(c,MRcurve([-1,-.78],[-.5,-.93],[.5,-.93],[1,-.78]),q.p[3],.01,.6)}
