 const n=Math.round(8+MRclamp((density-25)/75)*18);for(let k=0;k<n;k++){const x=(MRrand(k,index)-.5)*2.3,y=(MRrand(k+99,index)-.5)*1.7;MRellipse(c,x,y,.002,.005,p[k%p.length],.12)}
