 for(let k=0;k<5;k++){const root=k===4?0:m.progression[k],t=chordStarts[k],span=(chordStarts[k+1]||D)-t;const chord=[degree(root),degree(root+2),degree(root+6),degree(root+8)];add(t,span,'rain-air',chord,.3,0,{role:'harmony',spread:.4});add(t,Math.min(span,2.4),'rain-bass',[degree(root-7)],.52,-.06,{role:'bass'});add(t+.07,1.65,'rain-felt',[degree(root+2),degree(root+4),degree(root+8)],.28,.15,{role:'voicing',strum:.027});}
