/* Procedural instrument samples: damped modal resonators, plucked string,
 * pitched water transients and felt-piano partials. No external audio assets. */
const MR_SUSTAINED=Object.freeze(['rain-air']);
const MR_AUDIO_CACHE=new WeakMap();
function mrAudioCache(ctx){let v=MR_AUDIO_CACHE.get(ctx);if(v)return v;const sr=ctx.sampleRate,ir=ctx.createBuffer(2,Math.ceil(sr*2.1),sr);let seed=71237;const rnd=()=>{seed=(seed*16807)%2147483647;return seed/2147483647*2-1};for(let ch=0;ch<2;ch++){const a=ir.getChannelData(ch);let low=0;for(let i=0;i<a.length;i++){low=low*.53+rnd()*.47;const t=i/sr;a[i]=t<.025?0:low*Math.exp(-t*3.3)*Math.min(1,(t-.025)/.018)*.8;}}v={ir,samples:new Map()};MR_AUDIO_CACHE.set(ctx,v);return v;}
